"""Business logic for inventory service.

Intentionally imperfect: missing error handling, inconsistent type hints,
no logging, no docstrings on some methods.
"""

from models import Item


class InventoryService:
    def __init__(self):
        self._items = {}

    def get_item(self, sku) -> Item | None:
        return self._items.get(sku)

    def add_item(self, item: Item) -> None:
        self._items[item.sku] = item

    def update_quantity(self, sku, delta) -> bool:
        item = self._items.get(sku)
        if item is None:
            return False
        item.quantity += delta
        return True

    def deactivate_item(self, sku) -> bool:
        item = self._items.get(sku)
        if item is None:
            return False
        item.is_active = False
        return True

    def get_low_stock(self, threshold) -> list[Item]:
        return [item for item in self._items.values() if item.quantity < threshold]

    def get_all_items(self) -> list[Item]:
        return list(self._items.values())

"""FastAPI router for inventory service.

Intentionally missing: input validation, error responses, rate limiting,
authentication, and proper HTTP status codes.
"""

from fastapi import APIRouter
from models import Item
from service import InventoryService

router = APIRouter()
service = InventoryService()


@router.get("/items/{sku}")
def get_item(sku: str):
    item = service.get_item(sku)
    return item


@router.post("/items")
def add_item(item: Item):
    service.add_item(item)
    return {"status": "ok"}


@router.patch("/items/{sku}/quantity")
def update_quantity(sku: str, delta: int):
    service.update_quantity(sku, delta)
    return {"status": "ok"}


@router.get("/items/low-stock")
def low_stock(threshold: int):
    items = service.get_low_stock(threshold)
    return items
